const input = $input.first().json;

// Normalize incoming values
const email = String(input.email ?? "").trim().toLowerCase();
const firstName = String(input.first_name ?? "").trim();
const lastName = String(input.last_name ?? "").trim();
const company = String(input.company ?? "").trim();
const message = String(input.message ?? "").trim();
const eventId = String(input.event_id ?? "").trim();

// Validate minimum required information
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const valid = emailValid && message.length > 0 && eventId.length > 0;

// Only include non-empty values in a future CRM update
const crmProperties = { email };

if (firstName) crmProperties.firstname = firstName;
if (lastName) crmProperties.lastname = lastName;
if (company) crmProperties.company = company;

return [{
  json: {
    valid,
    event_id: eventId,
    email,
    first_name: firstName,
    last_name: lastName,
    company,
    company_type: String(input.company_type ?? "").trim().toLowerCase(),
    message,
    crm_update_preview: crmProperties
  }
}];

