parameters.jsCode:
const lead = $("Normalize Lead").first().json;
const search = $input.first().json;

// 1. Reject invalid input
if (lead.valid !== true) {
  throw new Error("INVALID_LEAD");
}

// 2. Validate the HubSpot response
if (
  !Number.isInteger(search.total) ||
  search.total < 0 ||
  !Array.isArray(search.results)
) {
  throw new Error("INVALID_CRM_RESPONSE");
}

// 3. No matching contact
if (search.total === 0) {
  if (search.results.length !== 0) {
    throw new Error("INCONSISTENT_SEARCH_RESULTS");
  }

  return [{
    json: {
      status: "not_found",
      email: lead.email,
      contact_id: null,
      review_required: false,
      next_action: "evaluate_for_creation",
      crm_write_performed: false
    }
  }];
}

// 4. Multiple matching contacts
if (search.total > 1 || search.results.length > 1) {
  return [{
    json: {
      status: "multiple_matches",
      email: lead.email,
      match_count: search.total,
      review_required: true,
      next_action: "manual_review",
      crm_write_performed: false
    }
  }];
}

// 5. Exactly one contact
if (search.total !== 1 || search.results.length !== 1) {
  throw new Error("INCONSISTENT_SEARCH_RESULTS");
}

const contact = search.results[0];
const crm = contact.properties || {};

if (!contact.id) {
  throw new Error("CONTACT_ID_MISSING");
}

if (
  String(crm.email ?? "").trim().toLowerCase() !== lead.email
) {
  throw new Error("CONTACT_EMAIL_MISMATCH");
}

// 6. Compare incoming information with CRM information
const conflicts = [];

function compare(field, incoming, existing) {
  const a = String(incoming ?? "").trim();
  const b = String(existing ?? "").trim();

  // Missing information is not automatically a conflict
  if (!a || !b) return;

  if (a.toLowerCase() !== b.toLowerCase()) {
    conflicts.push({
      field,
      incoming_value: a,
      crm_value: b
    });
  }
}

compare("firstname", lead.first_name, crm.firstname);
compare("lastname", lead.last_name, crm.lastname);
compare("company", lead.company, crm.company);

// 7. Return a safe decision
return [{
  json: {
    status: "found",
    email: lead.email,
    contact_id: String(contact.id),

    crm_company: crm.company ?? null,
    incoming_company: lead.company || null,

    lifecycle_stage: crm.lifecyclestage ?? null,
    contact_owner: crm.hubspot_owner_id ?? null,

    conflicts,
    review_required: conflicts.length > 0,

    next_action: conflicts.length > 0
      ? "manual_review"
      : "continue_qualification",

    crm_write_performed: false
  }
}];

const match = $input.first().json;
const lead = $("Normalize Lead").first().json;
const search = $("Search HubSpot Contact").first().json;

if (lead.valid !== true) {
  throw new Error("INVALID_LEAD");
}

// Only synthetic test records are allowed for now.
if (!/^[a-z0-9._+-]+@example\.com$/.test(lead.email)) {
  throw new Error("TEST_EMAIL_REQUIRED");
}

const incoming = lead.crm_update_preview || {};
const fields = ["firstname", "lastname", "company"];


const qualification =
  match.lead_intelligence_context?.qualification;

if (
  qualification?.schema_version !== "lead_qualification_v1" ||
  qualification.event_id !== lead.event_id ||
  String(qualification.contact_id ?? "") !==
    String(match.contact_id ?? "") ||
  qualification.crm_write_authorized !== false ||
  qualification.sales_task_creation_authorized !== false
) {
  throw new Error("INVALID_LEAD_QUALIFICATION");
}

// Keep a compact assessment for downstream operations.
// Do not copy raw notes, emails or full CRM history.
const qualificationSummary = {
  schema_version: qualification.schema_version,
  policy_version: qualification.policy_version,

  icp_fit: qualification.assessment.icp_fit.level,
  buying_intent: qualification.assessment.buying_intent.level,
  urgency: qualification.assessment.urgency.level,
  follow_up_risk: qualification.assessment.follow_up_risk.level,

  recommended_next_action:
    qualification.recommended_next_action,

  reason_codes: qualification.reason_codes,
  supporting_evidence_ids:
    qualification.supporting_evidence_ids,

  human_review_required:
    qualification.human_review_required === true,

  crm_write_authorized: false
};



const base = {
  event_id: lead.event_id,
  email: lead.email,
  contact_id: match.contact_id ?? null,
  dry_run: true,
  crm_write_performed: false,
  qualification_summary: qualificationSummary
};


function result(decision, properties, reason) {
  return [{
    json: {
      ...base,
      decision,
      proposed_properties: properties,
      reason
    }
  }];
}

// Case 1: Conflicting or duplicate CRM records
if (
  match.status === "multiple_matches" ||
  match.review_required === true
) {
  return result(
    "manual_review",
    null,
    "CRM identity or property conflict requires investigation"
  );
}

// Case 2: No existing contact
if (match.status === "not_found") {
  const properties = { email: lead.email };

  for (const field of fields) {
    const value = String(incoming[field] ?? "").trim();
    if (value) properties[field] = value;
  }

  return result(
    "propose_create",
    properties,
    "No matching contact found; creation needs further checks"
  );
}

// Case 3: Existing contact with no detected conflict
if (match.status === "found") {
  if (
    search.total !== 1 ||
    String(search.results?.[0]?.id) !==
      String(match.contact_id)
  ) {
    throw new Error("CRM_MATCH_INCONSISTENT");
  }

  const existing = search.results[0].properties;
  if (!existing) throw new Error("CRM_PROPERTIES_MISSING");

  // Only propose filling missing CRM fields
  const patch = {};

  for (const field of fields) {
    const newValue = String(incoming[field] ?? "").trim();
    const oldValue = String(existing[field] ?? "").trim();

    if (newValue && !oldValue) {
      patch[field] = newValue;
    }
  }

  if (Object.keys(patch).length === 0) {
    return result(
      "no_change",
      null,
      "Existing CRM properties are preserved"
    );
  }

  return result(
    "propose_fill_missing",
    patch,
    "Only missing CRM properties are candidates for update"
  );
}

throw new Error("UNKNOWN_CRM_MATCH_STATUS");

const lead = $("Normalize Lead").first().json;
const plan = $input.first().json;

if (lead.valid !== true) {
  throw new Error("INVALID_LEAD");
}

if (plan.dry_run !== true ||
    plan.crm_write_performed !== false) {
  throw new Error("DRY_RUN_REQUIRED");
}

const eventId = String(lead.event_id ?? "").trim();

if (!/^[A-Za-z0-9_-]{1,80}$/.test(eventId)) {
  throw new Error("INVALID_EVENT_ID");
}

// Build a consistent representation of the request.
// This is a readable demo key, not a cryptographic hash.
const requestKey = JSON.stringify({
  email: lead.email,
  first_name: lead.first_name,
  last_name: lead.last_name,
  company: lead.company,
  company_type: lead.company_type,
  message: lead.message
});

return [{
  json: {
    ...plan,
    event_id: eventId,
    request_key: requestKey,
    ledger_scope: "development_dry_run",
    execution_id: String($execution.id)
  }
}];

const incoming = $("Prepare Event Identity").first().json;

// Read all rows returned by the Data Table lookup.
// Ignore the empty placeholder produced by Always Output Data.
const rows = $input.all()
  .map(item => item.json)
  .filter(row => typeof row.event_id === "string");

let decision;
let reason;

// Case 1: Multiple ledger rows share the same event ID.
// This indicates a data-integrity problem.
if (rows.length > 1) {
  decision = "manual_review";
  reason = "Multiple ledger rows share the same event ID";

// Case 2: No previous record.
// This is a new event and may proceed to action planning.
} else if (rows.length === 0) {
  decision = "new_event";
  reason = "This event ID has not been recorded";

} else {
  const existing = rows[0];

  // Case 3: Same event ID but different request data.
  // Never treat this as a valid replay.
  if (existing.request_key !== incoming.request_key) {
    decision = "event_id_conflict";
    reason = "Same event ID was used for different data";

  // Case 4: The earlier dry-run was completed.
  } else if (existing.state === "completed_dry_run") {
    decision = "previously_processed";
    reason = "A matching dry-run event was already recorded";

  // Case 5: HubSpot contact creation was verified.
  // No additional contact should be created.
  } else if (
    existing.state === "crm_create_verified" ||
    existing.state === "crm_update_verified"
  ) {
    decision = "previously_processed";
    reason = "HubSpot contact creation was already verified";

  // Case 6: A create operation was started,
  // but the result has not been confirmed.
  } else if (existing.state === "pending_crm_create") {
    decision = "reconcile_required";
    reason = "Previous CRM create outcome is not confirmed";
  } else if (existing.state === "pending_crm_update") {
    decision = "reconcile_required";
    reason = "Previous CRM update outcome is not confirmed";

  // Case 7: Unexpected or unrecognized ledger state.
  } else {
    decision = "manual_review";
    reason = "Existing event state requires investigation";
  }
}

// Return the event decision.
// This node itself does not perform a HubSpot write.
return [{
  json: {
    event_id: incoming.event_id,
    request_key: incoming.request_key,
    ledger_decision: decision,
    reason,
    matching_rows: rows.length,
    dry_run: true,
    crm_write_performed: false
  }
}];

const ENABLE_TEST_WRITES = false;
const ALLOWED_EMAIL = "leadops.create103@example.com";

const lead = $("Normalize Lead").first().json;
const match = $("Evaluate CRM Match").first().json;
const plan = $("Plan Safe CRM Action").first().json;
const replay = $input.first().json;

if (!ENABLE_TEST_WRITES) {
  throw new Error("TEST_CRM_WRITES_DISABLED");
}

if (
  lead.valid !== true ||
  match.status !== "not_found" ||
  plan.decision !== "propose_create" ||
  plan.dry_run !== true ||
  plan.crm_write_performed !== false ||
  replay.ledger_decision !== "new_event"
) {
  throw new Error("CREATE_NOT_AUTHORIZED");
}

if (lead.email !== ALLOWED_EMAIL) {
  throw new Error("UNAUTHORIZED_TEST_EMAIL");
}

const properties = plan.proposed_properties;

if (
  !properties ||
  properties.email !== ALLOWED_EMAIL ||
  Object.keys(properties).some(
    key => !["email", "firstname", "lastname", "company"].includes(key)
  )
) {
  throw new Error("INVALID_CREATE_PROPERTIES");
}

return [{
  json: {
    event_id: replay.event_id,
    request_key: replay.request_key,
    email: lead.email,
    properties,
    action: "create_contact",
    dry_run: false,
    crm_write_performed: false
  }
}];

const authorized = $("Authorize Test Create").first().json;
const created = $("Create HubSpot Contact").first().json;
const actual = $input.first().json;

if (
  !created.id ||
  !actual.id ||
  String(created.id) !== String(actual.id)
) {
  throw new Error("CONTACT_ID_VERIFICATION_FAILED");
}

const expected = authorized.properties;
const stored = actual.properties || {};

for (const [key, value] of Object.entries(expected)) {
  const a = String(value ?? "").trim();
  const b = String(stored[key] ?? "").trim();

  const equal = key === "email"
    ? a.toLowerCase() === b.toLowerCase()
    : a === b;

  if (!equal) {
    throw new Error(`CRM_PROPERTY_MISMATCH: ${key}`);
  }
}

return [{
  json: {
    event_id: authorized.event_id,
    email: authorized.email,
    contact_id: String(actual.id),
    action: "create_contact",
    state: "crm_create_verified",
    crm_write_performed: true,
    verified: true,
    properties_checked: Object.keys(expected)
  }
}];

const ENABLE_TEST_UPDATES = false;
const ALLOWED_EMAIL = "leadops.update105@example.com";

const lead = $("Normalize Lead").first().json;
const match = $("Evaluate CRM Match").first().json;
const plan = $("Plan Safe CRM Action").first().json;
const replay = $input.first().json;

if (!ENABLE_TEST_UPDATES) {
  throw new Error("TEST_UPDATES_DISABLED");
}

if (
  lead.valid !== true ||
  lead.email !== ALLOWED_EMAIL ||
  match.status !== "found" ||
  match.email !== ALLOWED_EMAIL ||
  !match.contact_id ||
  match.review_required !== false ||
  plan.decision !== "propose_fill_missing" ||
  plan.dry_run !== true ||
  plan.crm_write_performed !== false ||
  replay.ledger_decision !== "new_event"
) {
  throw new Error("UPDATE_NOT_AUTHORIZED");
}

const properties = plan.proposed_properties;

if (
  !properties ||
  Object.keys(properties).length === 0 ||
  Object.entries(properties).some(
    ([key, value]) =>
      !["firstname", "lastname", "company"].includes(key) ||
      typeof value !== "string" ||
      !value.trim()
  )
) {
  throw new Error("UNSAFE_PATCH_PROPERTIES");
}

return [{
  json: {
    event_id: replay.event_id,
    request_key: replay.request_key,
    email: lead.email,
    contact_id: String(match.contact_id),
    properties,
    action: "update_contact",
    crm_write_performed: false
  }
}];

const authorized = $("Authorize Test Update").first().json;
const current = $input.first().json;

const stored = current.properties;

// Validate the latest HubSpot response.
if (!stored || typeof stored !== "object") {
  throw new Error("CRM_PROPERTIES_MISSING");
}

if (String(current.id) !== authorized.contact_id) {
  throw new Error("CONTACT_ID_CHANGED");
}

if (
  String(stored.email ?? "").trim().toLowerCase() !==
  authorized.email
) {
  throw new Error("CONTACT_EMAIL_CHANGED");
}

// Make sure the incoming patch is legitimate.
const patch = authorized.properties;

if (
  !patch ||
  typeof patch !== "object" ||
  Object.keys(patch).length === 0
) {
  throw new Error("INVALID_PATCH");
}

// Only allow filling missing fields.
for (const [field, incomingValue] of Object.entries(patch)) {

  if (!["firstname", "lastname", "company"].includes(field)) {
    throw new Error(`UNAUTHORIZED_FIELD: ${field}`);
  }

  const existingValue = String(stored[field] ?? "").trim();
  const newValue = String(incomingValue ?? "").trim();

  if (existingValue) {
    throw new Error(`FIELD_NO_LONGER_EMPTY: ${field}`);
  }

  if (!newValue) {
    throw new Error(`EMPTY_UPDATE_VALUE: ${field}`);
  }
}

// The update has been approved for this test.
// No HubSpot write has occurred yet.
return [{
  json: {
    event_id: authorized.event_id,
    request_key: authorized.request_key,
    email: authorized.email,
    contact_id: authorized.contact_id,
    properties: patch,
    action: "update_contact",
    preflight_verified: true,
    crm_write_performed: false
  }
}];

const authorized = $("Authorize Test Update").first().json;
const before = $("Read Current Contact Before Update").first().json;
const after = $input.first().json;

if (String(after.id) !== authorized.contact_id) {
  throw new Error("UPDATE_CONTACT_ID_MISMATCH");
}

const oldProperties = before.properties || {};
const newProperties = after.properties || {};

if (
  String(newProperties.email ?? "").trim().toLowerCase() !==
  authorized.email
) {
  throw new Error("UPDATE_EMAIL_MISMATCH");
}

const fields = ["firstname", "lastname", "company"];

for (const field of fields) {
  const actual = String(newProperties[field] ?? "").trim();

  if (Object.prototype.hasOwnProperty.call(
    authorized.properties, field
  )) {
    const expected =
      String(authorized.properties[field]).trim();

    if (actual !== expected) {
      throw new Error(`UPDATE_NOT_VERIFIED: ${field}`);
    }

  } else {
    const previous =
      String(oldProperties[field] ?? "").trim();

    if (actual !== previous) {
      throw new Error(`PROTECTED_FIELD_CHANGED: ${field}`);
    }
  }
}

return [{
  json: {
    event_id: authorized.event_id,
    email: authorized.email,
    contact_id: authorized.contact_id,
    action: "update_contact",
    state: "crm_update_verified",
    crm_write_performed: true,
    verified: true,
    updated_fields: Object.keys(authorized.properties)
  }
}];

const replay = $input.first().json;

if (replay.ledger_decision !== "reconcile_required") {
  throw new Error("RECONCILIATION_NOT_REQUIRED");
}

// Retrieve the original record from our existing ledger lookup.
const matches = $("Find Existing Event").all()
  .map(item => item.json)
  .filter(row => row.event_id === replay.event_id);

if (matches.length !== 1) {
  throw new Error("INVALID_LEDGER_ROW_COUNT");
}

const ledger = matches[0];

if (ledger.request_key !== replay.request_key) {
  throw new Error("REQUEST_KEY_MISMATCH");
}

const expectedAction = {
  pending_crm_create: "create_contact",
  pending_crm_update: "update_contact"
}[ledger.state];

if (!expectedAction) {
  throw new Error("UNSUPPORTED_PENDING_STATE");
}

// Parse the original operation recorded before the CRM write.
let intent;

try {
  intent = JSON.parse(ledger.result_json);
} catch (error) {
  throw new Error("INVALID_SAVED_INTENT_JSON");
}

if (
  !intent ||
  intent.event_id !== ledger.event_id ||
  intent.request_key !== ledger.request_key ||
  intent.action !== expectedAction
) {
  throw new Error("SAVED_INTENT_INCONSISTENT");
}

const email = String(intent.email ?? "")
  .trim()
  .toLowerCase();

const properties = intent.properties;

if (
  !/^[a-z0-9._+-]+@example\.com$/.test(email) ||
  !properties ||
  typeof properties !== "object" ||
  Array.isArray(properties) ||
  Object.keys(properties).length === 0
) {
  throw new Error("INVALID_RECONCILIATION_DATA");
}

for (const [field, value] of Object.entries(properties)) {
  if (
    !["email", "firstname", "lastname", "company"].includes(field) ||
    typeof value !== "string" ||
    !value.trim()
  ) {
    throw new Error(`INVALID_INTENDED_PROPERTY: ${field}`);
  }
}

if (
  expectedAction === "create_contact" &&
  properties.email !== email
) {
  throw new Error("CREATE_EMAIL_MISMATCH");
}

if (
  expectedAction === "update_contact" &&
  (!intent.contact_id || "email" in properties)
) {
  throw new Error("INVALID_UPDATE_INTENT");
}

return [{
  json: {
    event_id: ledger.event_id,
    ledger_row_id: ledger.id,
    ledger_state: ledger.state,
    action: expectedAction,
    email,
    contact_id: intent.contact_id
      ? String(intent.contact_id)
      : null,
    expected_properties: properties,
    investigation_only: true,
    crm_write_performed: false
  }
}];

const intent = $("Inspect Pending Ledger Entry").first().json;
const current = $input.first().json;

if (String(current.id ?? "") !== intent.contact_id) {
  throw new Error("RECONCILIATION_CONTACT_ID_MISMATCH");
}

const properties = current.properties;

if (!properties || typeof properties !== "object") {
  throw new Error("RECONCILIATION_PROPERTIES_MISSING");
}

const crmEmail = String(properties.email ?? "")
  .trim()
  .toLowerCase();

if (crmEmail !== intent.email) {
  throw new Error("RECONCILIATION_EMAIL_MISMATCH");
}

const comparisons = [];

for (const [field, expectedValue] of
  Object.entries(intent.expected_properties)) {

  const actualValue = String(properties[field] ?? "").trim();
  const expected = String(expectedValue ?? "").trim();

  comparisons.push({
    field,
    expected,
    actual: actualValue,
    matches: actualValue === expected
  });
}

const allMatch = comparisons.every(
  comparison => comparison.matches
);

return [{
  json: {
    event_id: intent.event_id,
    ledger_row_id: intent.ledger_row_id,
    contact_id: intent.contact_id,
    action: "update_contact",

    reconciliation_status: allMatch
      ? "expected_values_present"
      : "expected_values_not_confirmed",

    comparisons,

    next_action: allMatch
      ? "review_write_origin"
      : "manual_investigation",

    ledger_state_unchanged: true,
    crm_write_performed: false
  }
}];

