parameters.jsCode:
const intent = $("Inspect Pending Ledger Entry").first().json;
const search = $input.first().json;

if (
  intent.action !== "create_contact" ||
  intent.ledger_state !== "pending_crm_create"
) {
  throw new Error("INVALID_CREATE_RECONCILIATION");
}

if (
  !Number.isInteger(search.total) ||
  search.total < 0 ||
  !Array.isArray(search.results)
) {
  throw new Error("INVALID_HUBSPOT_SEARCH_RESPONSE");
}

const expected = intent.expected_properties;

if (
  !expected ||
  expected.email !== intent.email
) {
  throw new Error("INVALID_CREATE_INTENT");
}

let status;
let nextAction;
let contactId = null;
let comparisons = [];

// No contact was found.
if (search.total === 0 && search.results.length === 0) {

  status = "contact_not_found";
  nextAction = "manual_investigation";

// Multiple matches or inconsistent search results.
} else if (
  search.total !== 1 ||
  search.results.length !== 1
) {

  status = "ambiguous_contact_search";
  nextAction = "manual_review";

// One matching contact was found.
} else {

  const contact = search.results[0];
  const properties = contact.properties || {};

  contactId = String(contact.id ?? "");

  if (!contactId) {
    throw new Error("CONTACT_ID_MISSING");
  }

  const crmEmail = String(properties.email ?? "")
    .trim()
    .toLowerCase();

  if (crmEmail !== intent.email) {
    throw new Error("SEARCH_EMAIL_MISMATCH");
  }

  comparisons = Object.entries(expected).map(
    ([field, expectedValue]) => {

      const actual = String(properties[field] ?? "").trim();
      const wanted = String(expectedValue ?? "").trim();

      const matches = field === "email"
        ? actual.toLowerCase() === wanted.toLowerCase()
        : actual === wanted;

      return {
        field,
