const allowedTopics = new Set([
  "demo_meeting",
  "buyer_need",
  "urgency",
  "sales_follow_up",
  "technical_requirements",
  "company_context",
  "qualification_status",
  "internal_administration",
  "other"
]);

const allowedRelevance = new Set([
  "relevant",
  "unclear",
  "unrelated"
]);

const allowedSignals = new Set([
  "explicit",
  "implied",
  "none"
]);

const normalize = text =>
  String(text ?? "").replace(/\s+/g, " ").trim();

const validated = [];
const seenIds = new Set();

for (let i = 0; i < aiItems.length; i++) {
  // Recover the source note linked to this AI result.
  const source =
    $("Prepare Note Classification")
      .itemMatching(i).json;

  const result = aiItems[i].json.output;

  if (!result || typeof result !== "object") {
    throw new Error("INVALID_AI_OUTPUT");
  }

  const noteId = String(source.note_id);

  if (
    String(source.contact_id) !==
      String(context.crm.contact.contact_id) ||
    seenIds.has(noteId)
  ) {
    throw new Error("NOTE_IDENTITY_ERROR");
  }

  seenIds.add(noteId);

  if (
    !Array.isArray(result.topic_labels) ||
    result.topic_labels.some(
      label => !allowedTopics.has(label)
    ) ||
    !allowedRelevance.has(result.lead_relevance) ||
    !allowedSignals.has(result.intent_signal) ||
    !allowedSignals.has(result.urgency_signal) ||
    !allowedSignals.has(result.follow_up_signal)
  ) {
    throw new Error("INVALID_CLASSIFICATION_VALUES");
  }

  if (
    new Set(result.topic_labels).size !==
    result.topic_labels.length
  ) {
    throw new Error("DUPLICATE_TOPIC_LABELS");
  }

  if (
    typeof result.deadline_text !== "string" ||
    typeof result.summary !== "string" ||
    !Array.isArray(result.evidence_quotes)
  ) {
    throw new Error("INVALID_CLASSIFICATION_SCHEMA");
  }

  const sourceText = normalize(source.note_text);

  // Check that quoted evidence exists in the source.
  for (const quote of result.evidence_quotes) {
    if (
      typeof quote !== "string" ||
      !normalize(quote) ||
      !sourceText.includes(normalize(quote))
    ) {
      throw new Error(
        `UNSUPPORTED_EVIDENCE_QUOTE: ${noteId}`
      );
    }
  }

  if (
    result.deadline_text &&
    !sourceText.includes(
      normalize(result.deadline_text)
    )
  ) {
    throw new Error(
      `UNSUPPORTED_DEADLINE: ${noteId}`
    );
  }

  const hasSignal = [
    result.intent_signal,
    result.urgency_signal,
    result.follow_up_signal
  ].some(signal => signal !== "none");

  if (
    hasSignal &&
    result.evidence_quotes.length === 0
  ) {
    throw new Error(
      `SIGNAL_WITHOUT_EVIDENCE: ${noteId}`
    );
  }

  const warnings = [];

  if (
    result.urgency_signal !== "none" &&
    !result.topic_labels.includes("urgency")
  ) {
    warnings.push("URGENCY_TOPIC_MISSING");
  }

  if (source.text_truncated === true) {
    warnings.push("SOURCE_TEXT_TRUNCATED");
  }

  if (
    result.lead_relevance === "unrelated" &&
    hasSignal
  ) {
    warnings.push("UNRELATED_NOTE_HAS_SALES_SIGNAL");
  }

  validated.push({
    note_id: noteId,
    contact_id: String(source.contact_id),
    recorded_at: source.recorded_at,
    updated_at: source.updated_at,

    classification: {
      topic_labels: result.topic_labels,
      lead_relevance: result.lead_relevance,
      intent_signal: result.intent_signal,
      urgency_signal: result.urgency_signal,
      follow_up_signal: result.follow_up_signal,
