// Normalize timestamps only when their timezone is trustworthy.
// Never guess dates from ambiguous strings.
function utc(value, sourceField) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  const raw = String(value).trim();
  let date;

  if (/^\d{13}$/.test(raw)) {
    date = new Date(Number(raw));
  } else if (/^\d{10}$/.test(raw)) {
    date = new Date(Number(raw) * 1000);
  } else if (/T.*(?:Z|[+-]\d{2}:\d{2})$/i.test(raw)) {
    date = new Date(raw);
  }

  if (!date || Number.isNaN(date.getTime())) {
    issues.add(`UNVERIFIED_TIMESTAMP:${sourceField}`);
    return null;
  }

  return date.toISOString();
}

// A missing contact or inaccessible history does not mean
// that no previous activity occurred.
function activity(type) {
  if (!isFound) {
    return {
      status: match === "not_found"
        ? "not_retrieved_no_contact_match"
        : "blocked_ambiguous_identity",
      records: [],
      complete: false
    };
  }

  const value = history[type];

  if (
    !value ||
    typeof value !== "object" ||
    !Array.isArray(value.records)
  ) {
    return {
      status: "not_retrieved",
      records: [],
      complete: false
    };
  }

  const status = String(value.status || "unknown");

  const complete =
    ["loaded", "none_returned"].includes(status) &&
    value.has_more !== true &&
    (
      !Array.isArray(value.missing_ids) ||
      value.missing_ids.length === 0
    );

  return {
    status,
    records: value.records,
    complete
  };
}

