  e.incoming?.company_type_self_reported
);
const inquiry = value(e.incoming?.inquiry_message);

const sectorHint =
  /\b(biotech|biotechnology|pharma|pharmaceutical|diagnostic|diagnostics|genomics|life sciences?|bioanalytical|cro|cdmo)\b/i
    .test(sector);

const labNeedHint =
  /\b(lab|laboratory|laboratories|lims|eln|instrument|instruments|sample|samples|scientific data|assay|assays)\b/i
    .test(inquiry);

let fit = "unknown";

if (sectorHint && labNeedHint) {
  fit = "potential_fit_unverified";
} else if (sectorHint || labNeedHint) {
  fit = "possible_fit_unverified";
}

if (sectorHint) {
  reasons.add("SELF_REPORTED_LIFE_SCIENCES_SECTOR");
}

if (labNeedHint) {
  reasons.add("LABORATORY_USE_CASE_IN_INQUIRY");
}

reasons.add("COMPANY_IDENTITY_NOT_VERIFIED");

// 2. Buying intent: prioritize the incoming inquiry.
const denial =
  /\b(?:do not|don't|not|no)\s+(?:need|want|request|schedule|book)\b.{0,30}\b(?:demo|demonstration)\b/i
    .test(inquiry);

const asksForDemo =
  !denial &&
  /\b(?:need|want|request|schedule|book|arrange|see|show|interested in|looking for)\b.{0,55}\b(?:demo|demonstration)\b/i
    .test(inquiry);

const evaluationText =
  /\b(?:evaluating|evaluate|evaluation|pricing|quote|purchase|procure|pilot|trial)\b/i
    .test(inquiry);

const aiInterest = notes.some(n =>
  ["explicit", "implied"].includes(n.intent_signal)
);

let intent = "not_observed_in_available_evidence";

if (asksForDemo) {
  intent = "explicit_demo_request";
  reasons.add("EXPLICIT_DEMO_REQUEST");
} else if (evaluationText) {
  intent = "evaluation_interest_in_inquiry";
  reasons.add("EVALUATION_INTEREST_IN_INQUIRY");
} else if (aiInterest) {
  intent = "ai_note_indicated_interest_unverified";
  reasons.add("AI_NOTE_BUYING_SIGNAL_UNVERIFIED");
