  reasons.add("NEGATED_DEMO_REQUEST_REQUIRES_REVIEW");
}

// 3. Urgency: never invent a verified deadline.
const aiDeadlines = notes
  .map(n => value(n.deadline_text))
  .filter(Boolean);

const statedUrgency =
  /\b(?:urgent|asap|immediately|time[- ]sensitive|deadline|by tomorrow|by next week|this week|next week)\b/i
    .test(inquiry);

const urgency = statedUrgency || aiDeadlines.length
  ? "possible_time_sensitivity_unverified"
  : "not_observed";

if (statedUrgency) {
  reasons.add("STATED_URGENCY_UNVERIFIED");
}

if (aiDeadlines.length) {
  reasons.add("AI_NOTE_DEADLINE_UNVERIFIED");
}

// 4. Engagement: activity does not prove human response.
if (tasks.length) reasons.add("EXISTING_OPEN_TASK");
if (meetings.length) reasons.add("EXISTING_SCHEDULED_MEETING");
if (calls.length) reasons.add("CALL_ACTIVITY_RECORDED");
if (emails.length) reasons.add("EMAIL_ACTIVITY_RECORDED");

if (
  issueCodes.includes(
    "CONTACT_OWNER_MISSING_BUT_ACTIVITY_OWNER_PRESENT"
  )
) {
  reasons.add("OWNER_HANDOFF_NEEDS_REVIEW");
}

if (
  issueCodes.includes(
    "NOTE_DEADLINE_AND_MEETING_TIMING_NEED_COMPARISON"
  )
) {
  reasons.add("MEETING_TIMING_NEEDS_CONFIRMATION");
}

// 5. No SLA assessment without approved policy/timestamps.
reasons.add("FOLLOW_UP_SLA_NOT_CONFIGURED");

const match = value(identity.match_status);

const identityBlocked =
  match === "multiple_matches" ||
  identity.review_required === true ||
  asList(identity.conflicts).length > 0;

if (identityBlocked) {
  reasons.add("CRM_IDENTITY_REVIEW_REQUIRED");
}

if (
  !e.coverage?.activity_batches_complete &&
  match === "found"
) {
  reasons.add("ACTIVITY_COVERAGE_INCOMPLETE");
}

// 6. Recommend a bounded business action.
// Existing work takes precedence over new tasks or demos.
let nextAction;
let rationale;

if (identityBlocked) {
  nextAction = "review_crm_identity";
  rationale =
    "Resolve CRM identity or conflicting properties before taking a sales action.";

} else if (meetings.length && tasks.length) {
  nextAction = "review_existing_meeting_and_task";
  rationale =
    "An open task and scheduled meeting already exist. Confirm relevance, ownership and timing; do not duplicate them.";

} else if (meetings.length) {
  nextAction = "review_existing_meeting";
  rationale =
    "A scheduled meeting exists. Confirm its purpose and timing before proposing another booking.";

} else if (tasks.length) {
  nextAction = "review_existing_open_task";
  rationale =
    "An open task exists. Review its owner and purpose before suggesting additional follow-up.";

} else if (intent === "explicit_demo_request") {
  nextAction = "propose_human_demo_follow_up";
  rationale =
    "The incoming inquiry requests a demo. A human should validate fit, ownership and missing history before approved action.";

} else {
  nextAction = "gather_more_qualification_evidence";
  rationale =
    "Insufficient verified information to justify a specific automated sales action.";
}

// 7. Build the versioned qualification contract.
const qualification = {
  schema_version: "lead_qualification_v1",
  policy_version: "synthetic_lab_sales_policy_v1",
  policy_status: "DEVELOPMENT_ONLY_NOT_SCISPOT_POLICY",

  event_id: e.event_id,
  contact_id: identity.contact_id ?? null,

  assessment: {
    crm_identity: identityBlocked
      ? "needs_review"
      : match,

    icp_fit: {
      level: fit,
      verification_status: "unverified",
      sector_signal_from: sectorHint
        ? "self_reported"
        : null,
      laboratory_use_case_in_inquiry: labNeedHint
    },

    buying_intent: {
      level: intent,
      evidence_source: asksForDemo || evaluationText
        ? "incoming_inquiry"
        : aiInterest
          ? "ai_note_extraction"
          : "none_observed"
    },

    urgency: {
      level: urgency,
      unverified_note_deadline_texts: aiDeadlines
    },

    engagement: {
      open_task_count: tasks.length,
      scheduled_meeting_count: meetings.length,
      recorded_call_count: calls.length,
      recorded_email_count: emails.length,
      first_human_response_verified:
        facts.first_human_response_verified === true,
      actual_human_contact_status:
        facts.actual_human_contact_status ?? "unknown"
    },

    follow_up_risk: {
      level: "cannot_determine",
      reason:
        "No approved response SLA or verified first-response timestamp."
    },

    confidence: identityBlocked
      ? "limited_identity_conflict"
      : match === "not_found"
        ? "limited_no_matching_crm_history"
        : !e.coverage?.activity_batches_complete
          ? "limited_history_coverage"
          : "provisional_unverified_company_and_engagement"
  },

  supporting_evidence_ids: {
    note_ids: notes.map(n => String(n.note_id)),
    task_ids: tasks.map(t => String(t.task_id)),
    meeting_ids: meetings.map(m => String(m.meeting_id)),
    call_ids: calls.map(c => String(c.call_id)),
    email_ids: emails.map(m => String(m.email_id))
  },

  evidence_issue_codes: issueCodes,
  reason_codes: [...reasons].sort(),

  recommended_next_action: nextAction,
  recommendation_rationale: rationale,

  // All actions remain advisory in this MVP.
  human_review_required: true,
  crm_write_authorized: false,
  sales_task_creation_authorized: false
};

return [{
  json: {
    ...original,
    lead_intelligence_context: {
      ...ctx,
      qualification
    }
  }
}];

const plan = $input.first().json;

const ctx = $("Evaluate Lead Qualification")
  .first().json.lead_intelligence_context;

const evidence = ctx?.evidence_summary;
const qualification = ctx?.qualification;

if (
  evidence?.schema_version !== "lead_evidence_v1" ||
  qualification?.schema_version !== "lead_qualification_v1"
) {
  throw new Error("INVALID_SALES_ACTION_CONTEXT");
}

if (
  plan.event_id !== evidence.event_id ||
  plan.event_id !== qualification.event_id ||
  String(plan.contact_id ?? "") !==
    String(evidence.identity?.contact_id ?? "")
) {
  throw new Error("SALES_ACTION_IDENTITY_MISMATCH");
}

const blockers = [];
const add = reason => {
  if (!blockers.includes(reason)) blockers.push(reason);
};

const assessment = qualification.assessment;
const facts = evidence.facts;
const identity = evidence.identity;

const openTasks = facts.tasks?.open_tasks ?? [];
const meetings = facts.meetings?.scheduled_meetings ?? [];
const calls = facts.calls?.records ?? [];
const emails = facts.emails?.records ?? [];

const contactId = identity.contact_id ?? null;
const ownerId = identity.contact_owner_id || null;

// Require a uniquely identified existing contact.
if (
  identity.match_status !== "found" ||
  !contactId ||
  identity.review_required ||
  (identity.conflicts ?? []).length > 0
) {
  add("CRM_IDENTITY_NOT_SAFE");
}

// We only create tasks after contact-data planning
// has determined no contact modification is needed.
if (plan.decision !== "no_change") {
  add("CONTACT_OPERATION_NOT_CLEARED");
}

// The qualification must identify explicit demo intent.
if (
  assessment.buying_intent.level !==
  "explicit_demo_request"
) {
  add("NO_EXPLICIT_DEMO_REQUEST");
}

// Use provisional ICP fit only for human-reviewed proposals.
if (![
  "potential_fit_unverified",
  "possible_fit_unverified"
].includes(assessment.icp_fit.level)) {
  add("INSUFFICIENT_ICP_EVIDENCE");
}

// Never create another task when equivalent work
// might already be represented by existing activities.
if (openTasks.length > 0) {
  add("EXISTING_OPEN_TASK");
}

if (meetings.length > 0) {
  add("EXISTING_SCHEDULED_MEETING");
}

// Previous communication requires human inspection.
if (calls.length > 0 || emails.length > 0) {
  add("EXISTING_COMMUNICATION_NEEDS_REVIEW");
}

// Missing history means we cannot safely rule out duplicates.
if (evidence.coverage?.activity_batches_complete !== true) {
  add("INCOMPLETE_CRM_ACTIVITY_HISTORY");
}

// Require a real contact-level owner before assignment.
if (!ownerId) {
  add("CONTACT_OWNER_NOT_ASSIGNED");
}

// Human approval is always required in this MVP.
const eligible = blockers.length === 0;

const salesTaskGate = {
  schema_version: "sales_task_gate_v1",
  policy_version: "synthetic_lab_sales_policy_v1",

  event_id: plan.event_id,
  contact_id: contactId,
  proposed_owner_id: ownerId,

  decision: eligible
    ? "eligible_for_human_approval"
    : "do_not_create_task",

  blocker_codes: blockers,

  proposed_action: eligible
    ? "create_demo_follow_up_task"
    : null,

  human_approval_required: true,
  approval_status: "not_approved",

  task_write_authorized: false,
  task_created: false,
  crm_write_performed: false
};

return [{
  json: {
    ...plan,
    sales_task_gate: salesTaskGate
  }
}];
